import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Playlist from './components/Playlist';
import Player from './components/Player';
import Library from './components/Library';
import SongDetailWindow from './components/SongDetailWindow';
import Playlists from './components/Playlists';
import songsData from './data/songs';

function App() {
  const [songs, setSongs] = useState(songsData);
  const [filteredSongs, setFilteredSongs] = useState(songsData);
  const [currentSong, setCurrentSong] = useState(songsData[0]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [librarySongs, setLibrarySongs] = useState([]);
  const [currentView, setCurrentView] = useState('playlist');
  const [detailSong, setDetailSong] = useState(null);

  // New states for playlist creation
  const [selectedSongs, setSelectedSongs] = useState([]);
  const [playlists, setPlaylists] = useState([]);
  const [selectedPlaylist, setSelectedPlaylist] = useState(null);

  const handleSongSelect = (song) => {
    setCurrentSong(song);
    setIsPlaying(true);
  };

  const handleToggleSelect = (songId) => {
    if (selectedSongs.includes(songId)) {
      setSelectedSongs(selectedSongs.filter(id => id !== songId));
    } else {
      setSelectedSongs([...selectedSongs, songId]);
    }
  };

  const handleCreatePlaylist = () => {
    if (selectedSongs.length === 0) return;
    const newPlaylist = {
      id: playlists.length + 1,
      name: `Playlist ${playlists.length + 1}`,
      songs: songs.filter(song => selectedSongs.includes(song.id)),
    };
    setPlaylists([...playlists, newPlaylist]);
    setSelectedSongs([]);
    setCurrentView('playlists');
  };

  const handleSelectPlaylist = (playlist) => {
    setSelectedPlaylist(playlist);
    setCurrentView('playlistDetail');
  };

  const handleSearch = (searchTerm) => {
    if (!searchTerm) {
      setFilteredSongs(songs);
    } else {
      const filtered = songs.filter((song) =>
        song.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        song.artist.toLowerCase().includes(searchTerm.toLowerCase()) ||
        song.album.toLowerCase().includes(searchTerm.toLowerCase())
      );
      setFilteredSongs(filtered);
    }
  };

  const handleNext = () => {
    const currentIndex = filteredSongs.findIndex((song) => song.id === (detailSong ? detailSong.id : currentSong.id));
    const nextIndex = (currentIndex + 1) % filteredSongs.length;
    const nextSong = filteredSongs[nextIndex];
    if (detailSong) {
      setDetailSong(nextSong);
    } else {
      setCurrentSong(nextSong);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const currentIndex = filteredSongs.findIndex((song) => song.id === (detailSong ? detailSong.id : currentSong.id));
    const prevIndex = (currentIndex - 1 + filteredSongs.length) % filteredSongs.length;
    const prevSong = filteredSongs[prevIndex];
    if (detailSong) {
      setDetailSong(prevSong);
    } else {
      setCurrentSong(prevSong);
      setIsPlaying(true);
    }
  };

  const handleAddToLibrary = (song) => {
    if (!librarySongs.find((s) => s.id === song.id)) {
      setLibrarySongs([...librarySongs, song]);
    }
  };

  const handleRemoveFromLibrary = (songId) => {
    setLibrarySongs(librarySongs.filter((song) => song.id !== songId));
  };

  const handleViewChange = (view) => {
    setCurrentView(view);
    if (view !== 'playlistDetail') {
      setSelectedPlaylist(null);
    }
  };

  const openDetailWindow = (song) => {
    setDetailSong(song);
  };

  const closeDetailWindow = () => {
    setDetailSong(null);
  };

  useEffect(() => {
    setFilteredSongs(songs);
  }, [songs]);

  return (
    <div className="app">
      <Header />
      <div className="main-content">
        <Sidebar onSearch={handleSearch} onViewChange={handleViewChange} currentView={currentView} />
        <div className="right-column">
          {(currentView === 'playlist' || currentView === 'createPlaylist') && (
            <>
              <Playlist
                songs={filteredSongs}
                onSongSelect={handleSongSelect}
                currentSong={currentSong}
                onToggleSelect={currentView === 'createPlaylist' ? handleToggleSelect : undefined}
                selectedSongs={currentView === 'createPlaylist' ? selectedSongs : []}
              />
              {currentView === 'createPlaylist' && (
                <button onClick={handleCreatePlaylist} disabled={selectedSongs.length === 0}>
                  Create Playlist
                </button>
              )}
            </>
          )}
          {currentView === 'library' && (
            <Library
              librarySongs={librarySongs}
              onSongSelect={handleSongSelect}
              currentSong={currentSong}
              onRemove={handleRemoveFromLibrary}
              onOpenDetail={openDetailWindow}
            />
          )}
          {currentView === 'playlists' && (
            <Playlists playlists={playlists} onSelectPlaylist={handleSelectPlaylist} />
          )}
          {currentView === 'playlistDetail' && selectedPlaylist && (
            <Playlist
              songs={selectedPlaylist.songs}
              onSongSelect={handleSongSelect}
              currentSong={currentSong}
              onToggleSelect={() => {}}
              selectedSongs={[]}
            />
          )}
          <Player
            song={currentSong}
            isPlaying={isPlaying}
            setIsPlaying={setIsPlaying}
            onNext={handleNext}
            onPrev={handlePrev}
          />
        </div>
      </div>
      {detailSong && (
        <SongDetailWindow
          song={detailSong}
          onClose={closeDetailWindow}
          onNext={handleNext}
          onPrev={handlePrev}
        />
      )}
    </div>
  );
}

export default App;
